        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                close = data.Bars[symbol].Close

                if ticker == "AAPL":
                    if symbol in self.previous_closes and close < self.previous_closes[symbol]:
                        self.aapl_red_streak += 1
                    else:
                        self.aapl_red_streak = 0

                self.previous_closes[symbol] = close

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        spy_bar = data.Bars[self.spy]
        aapl_bar = data.Bars[self.aapl]

        if self.strategy_a_shares > 0:
            if self._crosses_below(self.spy_sma_50, spy_bar.Close):
                self.MarketOrder(self.spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

        if self.strategy_b_shares > 0:
            if self.aapl_rsi_14.IsReady and self.aapl_rsi_14.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

        if self.strategy_a_shares == 0:
            if self._crosses_above(self.spy_sma_200, spy_bar.Close):
                quantity = int((self.Portfolio.TotalPortfolioValue * 0.40) / spy_bar.Close)
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)
                    self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0:
            if self.aapl_rsi_14.IsReady and self.aapl_red_streak >= 3:
                cash_amount = 20000
                if self.Portfolio.Cash >= cash_amount:
                    quantity = int(cash_amount / aapl_bar.Close)
                    if quantity > 0:
                        self.MarketOrder(self.aapl, quantity)
                        self.strategy_b_shares = quantity

    def _crosses_above(self, indicator, price):
        return (
            indicator.IsReady
            and indicator.Window.Count > 1
            and price > indicator.Current.Value
            and self.Securities[indicator.Symbol].Close <= indicator.Window[1].Value
        )

    def _crosses_below(self, indicator, price):
        return (
            indicator.IsReady
            and indicator.Window.Count > 1
            and price < indicator.Current.Value
            and self.Securities[indicator.Symbol].Close >= indicator.Window[1].Value
        )
