class ParallelStrategiesAlgorithm(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.closes = {ticker: [] for ticker in self.symbols}
        self.opens = {ticker: [] for ticker in self.symbols}

        self.a_lot = 0
        self.b_lot = 0

        self.aapl_avg_gain = None
        self.aapl_avg_loss = None
        self.aapl_rsi = None

    def on_data(self, data: Slice):
        if any(symbol not in data.bars for symbol in self.symbols.values()):
            return

        for ticker, symbol in self.symbols.items():
            bar = data.bars[symbol]
            self.opens[ticker].append(float(bar.open))
            self.closes[ticker].append(float(bar.close))

        self._update_aapl_rsi()

        spy = self.closes["SPY"]
        aapl = self.closes["AAPL"]

        # SPY cross rules need both yesterday's and today's 200-day SMA.
        # RSI(14) needs 15 closes; requiring 201 closes ensures all rule
        # indicators and rolling windows are fully formed.
        if len(spy) < 201 or self.aapl_rsi is None:
            return

        # Sells are evaluated before buys.
        if self.a_lot > 0:
            previous_sma_50 = sum(spy[-51:-1]) / 50.0
            current_sma_50 = sum(spy[-50:]) / 50.0
            if spy[-2] >= previous_sma_50 and spy[-1] < current_sma_50:
                self.market_order(self.symbols["SPY"], -self.a_lot)
                self.a_lot = 0

        if self.b_lot > 0 and self.aapl_rsi > 60:
            self.market_order(self.symbols["AAPL"], -self.b_lot)
            self.b_lot = 0

        if self.a_lot == 0:
            previous_sma_200 = sum(spy[-201:-1]) / 200.0
            current_sma_200 = sum(spy[-200:]) / 200.0
            if spy[-2] <= previous_sma_200 and spy[-1] > current_sma_200:
                quantity = int((0.40 * self.portfolio.total_portfolio_value) / spy[-1])
                if quantity > 0:
                    self.market_order(self.symbols["SPY"], quantity)
                    self.a_lot = quantity

        if self.b_lot == 0:
            red_three_days = (
                aapl[-1] < aapl[-2]
                and aapl[-2] < aapl[-3]
                and aapl[-3] < aapl[-4]
            )
            if red_three_days and self.portfolio.cash >= 20_000:
                quantity = int(20_000 / aapl[-1])
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.b_lot = quantity

    def _update_aapl_rsi(self):
        closes = self.closes["AAPL"]
        if len(closes) < 2:
            return

        change = closes[-1] - closes[-2]
        gain = max(change, 0.0)
        loss = max(-change, 0.0)

        if len(closes) == 15:
            gains = []
            losses = []
            for i in range(1, 15):
                delta = closes[i] - closes[i - 1]
                gains.append(max(delta, 0.0))
                losses.append(max(-delta, 0.0))
            self.aapl_avg_gain = sum(gains) / 14.0
            self.aapl_avg_loss = sum(losses) / 14.0
        elif len(closes) > 15:
            self.aapl_avg_gain = ((self.aapl_avg_gain * 13.0) + gain) / 14.0
            self.aapl_avg_loss = ((self.aapl_avg_loss * 13.0) + loss) / 14.0
        else:
            return

        if self.aapl_avg_loss == 0:
            self.aapl_rsi = 100.0
        elif self.aapl_avg_gain == 0:
            self.aapl_rsi = 0.0
        else:
            rs = self.aapl_avg_gain / self.aapl_avg_loss
            self.aapl_rsi = 100.0 - (100.0 / (1.0 + rs))
